export const pageData_NmcLoan_documentsList = [
    'Վարկի տրամադրման դիմում-հայտ անձնագիր կամ նույնականացման քարտ ինչպես նաև, սոցիալական քարտ կամ սոցիալական քարտ չունենալու մասին տեղեկանք (ընդ որում սոցիալական քարտ և սոցիալական քարտ չունենալու մասին տեղեկանք չի պահանջվում, եթե ներկայացվել է նույնականացման քարտ), ամուսնության վկայական (առկայության դեպքում),անչափահաս երեխաների ծննդյան վկայական (առկայության դեպքում),տեղեկանք աշխատանքի վայրից աշխատավարձի չափի մեծության մասին, որի տրամադրման ժամկետը Բանկին ներկայացման օրվա դրությամբ չպետք է գերազանցի 30 օրացույցային օրը,անհատական հաշվի քաղված Հաճախորդի ինքնազբաղված լինելու դեպքում`Հարկ վճարողի հարկային համարը (ՀՎՀՀ)Գրանցման վկայական, կանոնադրություն (առկայության դեպքում)Գործունեության տվյալ տեսակով զբաղվելու թույլտվության փաստաթղթերը, եթե օրենսդրության համաձայն տվյալ գործունեության համար անհրաժեշտ է համապատասխան մարմինների կողմից հատուկ թույլտվություն Վերջին 1 տարվա ֆինանսական և հարկային հաշվետվությունները` հաստատված հարկային մարմինների կողմիցՎերջին 6 ամիսների եկամուտների և ծախսերի հաշվետվությունները/գրառումները (առկայության դեպքում)ձեռք բերվող անշարժ գույքի գնահատման հաշվետվություն,վաճառվող գույքի սեփականության վկայականը,վաճառվող անշարժ գույքի ձեռք բերման հիմքերը,անշարժ գույքի սեփականատերերի անձնագրերը,տեղեկատվություն՝ երաշխավորող անձի/անց վերաբերյալ (պահանջի դեպքում),անհրաժեշտության դեպքում կարող են պահանջվել նաև այլ փաստաթղթեր',
  
  ];

