export const pageData_InvestDosDontsPost_dos = [{"title":"Գնահատել ռիսկերը","text":"Շարքեր ներդրողների համար ռիսկի ընդունելի մակարդակը տարբեր է, և նախքան ներդրում կատարելը՝ ինքներդ ձեզ համար պետք է որոշեք, թե առավելագույնը որքան գումար եք պատրաստ կորցնել, եթե հանգամանքները դասավորվեն ոչ ձեր օգտին, ինչպես կանխատեսում էիք:"},{"title":"Ինքնակրթվել","text":"Ներդրում կատարելիս առաջին հերթին կարևոր է ուսումնասիրել, հասկանալ, թե ինչ գործիքներ են գործում շուկայում, և որքան ձեզ համար կարող որպահ ուղենիշ, որոնք կարող են վկայել ապագա գործողությունների պլանավորման համար: Շուկաներում փոփոխությունները թավականին արագ են ընթանում, ուստի ավելացված պատասխանատվությամբ վերջին տեխնոլոգիաների արագացմամբ, ու այդ ամենին գրագետ քայլերով կարողանալու համար:"},{"title":"Իրականացնել դիվերսիֆիկացիա","text":"Ներդրումային տարբեր ակտիվների ներդրում են փոխկապակցված տարբեր ռիսկեր, հետևաբար լավ տարբերակ է համարվում տարբատեսակ ակտիվներում ներդրումներ կատարելը, որոշ ռիսկերի ազդեցության չափը ամրողջ արդյունքի վրա նվազեցնելու համար:"},{"title":"Նախապես մշակել ռազմավարություն","text":"Ներդրումների ընթացքում առաջ մոտեցված ու մշակված գործողությունների հաջորդականությունը թույլ կտա շուկայական փոփոխնային պայմաններում առավել հասկանալ ու դրանցից բխող քայլերը ու դրանցից բխող կայացվող որոշումների հիմքում: Հայացվող որոշումների հիմքում այս է ընկած գրագետ ներդրումների հիմքում:"}];

export const pageData_InvestDosDontsPost_donts = [{"title":"Մի հետևեք ամբոխին","text":"Հետևել որիշներին ու կատարել ներդրումներ, որովհետև մյուսներն են դա անում, սա հաճախ սխալների պատճառ է հանդիսանում: Այն նույն ձևով է կատարում, նույն արդյունքը շառ ընկար ես, կամ ցուցադր ադրավ ներդրումը մաս է իր ընդունելի ներդրումային ռազմավարությանը, որը ձեր ռազմավարությանը, որը ձեր ռազմավարությանը, որը ձեր ռազմաշիմերում չի կարող ինչ արդյունունքներից չընկնված:"},{"title":"Մի հիմնվեք բացառապես հավանականության վրա","text":"Ներդրումներին վերաբերվող վստահություն ունեցող ընկնված են դրդապատճառներ՝ աշխարհաքաղաքական, ինստիտուցիոնալ, հոգեբանական կամ այլ, դրանց խորությամբ ուստումնասիրության արդյունքում է հնարավոր կատարել լրջահեռավոր որոշումները:"},{"title":"Մի կայացրեք էմոցիոնալ որոշումներ","text":"Ձեր որոշումների վրա ազդում են տարբեր գործոններ, և դժվար է առանց նախապես մշակված ռազմավարության երևել էմոցիաներին ու կատարել ներդրումներ, ինչը կարող է հանգեցնել ոչ ցանկալի արդյունքների: Ներդրումներ կատարելիս պետք է կատարվեն սեփական դատողությունների և ռազմավարության վրա հիմնված:"},{"title":"Մի ներդրեք վերջին գումարը","text":"Ներդրումներ կատարելով այն գումարով, որը նախատեսված է ընթացիկ ծախսերի համար, կավելացնեք ֆինանսական ճնշումը: Ինչքանոք թույլ չի տա կայացնել ներդրումային որոշումներ, ինչը հանգեցնում է շտապողականության:"}];

