export const pageData_LoanCard_loanTerms = [{"id":1,"title":"Ովքեր կարող են դիմել","content":"Բանկի վճարային քարտի միջոցով աշխատավարձ ստացող՝ 18 – 65 տարեկան ՀՀ ռեզիդենտ ֆիզիկական անձինք, ովքեր վարկի սպասարկման ողջ ընթացքում չեն բոլորի 65 տարին"},{"id":2,"title":"Վարկավորման ձև"},{"id":3,"title":"Վարկավորման գումար","content":"100,000 - 10,000,000 ՀՀ դրամ, ոչ ավել քան փոխանցվող աշխատավարձի տասնհինգապատիկ"},{"id":4,"title":"Մարման ժամկետ","content":"12 - 60 ամիս"},{"id":5,"title":"Անվանական տոկոսադրույք","content":"16%"},{"id":6,"title":"Տարեկան փաստացի տոկոսադրույք","content":"19.62%"},{"id":7,"title":"Տրամադրման եղանակ"},{"id":8,"title":"Վճարման օր"},{"id":9,"title":"Քաղվածքի օր","content":"Մինչև յուրաքանչյուր ամսվա 10-ը"},{"id":10,"title":"Տույժեր"},{"id":11,"title":"Այլ արտոնություններ","content":"Անշարժ գույքի գրավով ապահովված սպառողական և ավտովարկերի դեպքում վարկի տարեկան տոկոսադրույքը կարող է նվազեցվել մինչև 0.5 տոկոսային կետով:"},{"id":12,"title":"Այլ դրույթներ","content":"60 և ավել օրվա ընթացքում գործատուի կողմից աշխատավարձը և/կամ դրան հավասարեցված վճարները Բանկի քարտին չփոխանցելու դեպքում, անգրավ վարկի/օվերդրաֆտի վարկային պայմանագրում նշված տարեկան տոկոսադրույքի փոխարեն կիրառվում է նշված ժամանակահատվածի լրանալու օրվա դրությամբ անգրավ վարկատեսակով սահմանված տարեկան անվանական տոկոսադրույքը գումարած մեկ տոկոսային կետ:"},{"id":13,"title":"Տրամադրման կամ մերժման վերաբերյալ որոշումների կայացման Ժամկետներ"}];

