export const pageData_EvocaTouchPage_reviews = [{"id":1,"text":"Հայաստանի իրականության մեջ բացառիկ հրաշք բանկ: Միայն այս հնարավորությունը ընձեռելով երիտասարդ ընտանիքներին ` նման ցածր տոկոսով բնակարան ձեռք բերել, արժանի է մեծ հարգանքի: Շնորհակալ ենք, որ Դուք կաք:","author":"Սուսաննա Վանյան","role":"Հաճախորդ"},{"id":2,"text":"Գերազանց սպասարկում, ընտիր ու հավես անձնակազմ Ազատության մասնաճյուղում: Վարկային բաժնից շատ շնորհակալ եմ, վարկս ձևակերպվեց առանց ավելորդ քաշքշուկների` հեշտ, արագ, որակով: Սպասարկման...","author":"Նունե Գևորգյան","role":"Հաճախորդ"},{"id":3,"text":"Դեպի նոր իրականություն. ահա թե ուր ենք մենք շարժվում ամեն մի նախագիծ Evocabank-ի հետ հաջողությամբ ավարտելիս: Ավելի քան 5 տարի համագործակցելով` կարելի է ասել, որ միասին անցել ենք մի մեծ ճանապարհ` լի...","author":"Արամ Ազարյան","role":"Indigo Branding-ի հիմնադիր"},{"id":4,"text":"Լավագույն նորարարական և թվային բանկ` լավագույն ծառայություններով և անձնակազմով:","author":"Էլեն Վարդանյան","role":"Հաճախորդ"},{"id":5,"text":"Բանկ, որ իր ռեբրենդինգի շքեղ միջոցառմամբ ու աշխատանքային ձևաչափով բանկային ոլորտում ամրապնդեց որակ և ճաշակ թելադրեց: Evocabank-ն առաջին իսկ վայրկյանից ստիպեց նորովի և ժամանակակից...","author":"Կամո Թովմասյան","role":"KAMOBLOG մեդիա-հարթակի հիմնադիր, influencer"}];

